import networkx as nx

def compute_girth(G):
    girth = float('inf')
    for v in G.nodes():
        dist = {v: 0}
        queue = [v]
        while queue:
            next_queue = []
            for u in queue:
                for w in G.neighbors(u):
                    if w not in dist:
                        dist[w] = dist[u] + 1
                        next_queue.append(w)
                    elif dist[w] >= dist[u]:
                        girth = min(girth, dist[u] + dist[w] + 1)
            queue = next_queue
    return girth

# K_{5,5} bipartite graph
G = nx.complete_bipartite_graph(5, 5)
final_edges = sorted([(min(u,v), max(u,v)) for u,v in G.edges()])

print("=== K_{5,5} Complete Bipartite Graph ===")
print(f"Vertices: 0–9  |  Partition A={{0,1,2,3,4}}, B={{5,6,7,8,9}}")
print(f"Number of edges: {len(final_edges)}")
print(f"Girth: {compute_girth(G)}")
print(f"Triangles: {sum(nx.triangles(G).values())//3}")
print(f"Connected: {nx.is_connected(G)}")
print()
print("Edge list:")
for e in final_edges:
    print(f"  {e}")
